function esc(value) { return String(value ?? '').replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;'); }
function tag(name, value) { return value == null ? '' : `<${name}>${esc(value)}</${name}>`; }
function nodeXml(row) { const [number,name,endpoint,rigid,type,weight,ref,connection,od,wall,corrosion,insulation,position,bendRadius,bendType,sif,alpha]=row; return `<Node>${tag('NodeNumber',number)}${tag('NodeName',name)}${tag('Endpoint',endpoint)}${tag('Rigid',rigid)}${tag('ComponentType',type)}${tag('Weight',weight)}${tag('ComponentRefNo',ref)}${tag('ConnectionType',connection)}${tag('OutsideDiameter',od)}${tag('WallThickness',wall)}${tag('CorrosionAllowance',corrosion)}${tag('InsulationThickness',insulation)}${tag('Position',position)}${tag('BendRadius',bendRadius)}${tag('BendType',bendType)}${tag('SIF',sif)}${tag('AlphaAngle',alpha)}</Node>`; }
function branchXml([name,temps,pressures,material,insulationDensity,fluidDensity,nodes]) { const temperature=temps.map((v,i)=>tag(`Temperature${i+1}`,v)).join(''); const pressure=pressures.map((v,i)=>tag(`Pressure${i+1}`,v)).join(''); return `<Branch>${tag('Branchname',name)}<Temperature>${temperature}</Temperature><Pressure>${pressure}</Pressure>${tag('MaterialNumber',material)}${tag('InsulationDensity',insulationDensity)}${tag('FluidDensity',fluidDensity)}${nodes.map(nodeXml).join('')}</Branch>`; }
